            engineeringData: { blockDesign: "Vermicular Graphite Cast Iron (CGI) 90-degree V6 closed deck. Lightweight but immensely strong.", crankshaft: "Forged Steel, highly balanced.", pistonSpeed: "14.2 m/s @ 4500 RPM.", alternator: "150 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with omega combustion bowls.", wristPinDiameter: "30 mm", connectingRodLength: "154 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "60.0 mm", rodRatio: "1.78" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-swirl 4-valve per cylinder (24V DOHC) architecture.", valveSizes: "Intake: 28.5 mm / Exhaust: 26.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad Camshafts driven by rear chain assembly.", lifterType: "Hydraulic Roller Finger Follower.", specialFeature: "Common Rail Direct Injection at 2000 Bar." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Chain-driven internal gear pump.", thermostatOpening: "87°C.", oilCooler: "Massive Water-to-Oil heat exchanger in the V." }, fuelSystem: { systemType: "Common Rail Direct Injection.", maxPressure: "2,000 Bar.", injectors: "Bosch Piezo-Electric." }, tuningLimits: { maxSafeTorqueStock: "Approx. 650 Nm (DSG clutch limit).", maxSafePowerStock: "Approx. 340 hp.", maxSafeRPM: "4800 RPM", weakestLink: "The DL501 DSG transmission clutches and the factory turbocharger capacity." }, electrical: { coils: "N/A", ecu: "Bosch EDC17C46" } },
