            engineeringData: { blockDesign: "All-Aluminum 90-degree V6 closed deck (EA837). Features Alusil cylinder walls. Incredibly robust.", crankshaft: "Forged Steel, highly balanced.", pistonSpeed: "15.5 m/s @ 6500 RPM.", alternator: "150 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with heavily reinforced skirts designed to survive supercharger boost.", wristPinDiameter: "22 mm", connectingRodLength: "153 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "65.0 mm", crankRodJournal: "56.0 mm", rodRatio: "1.72" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-flow 4-valve per cylinder (24V DOHC).", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Quad Camshafts driven by rear chain.", lifterType: "Hydraulic Roller Finger Follower.", specialFeature: "Eaton TVS1320 Supercharger providing 100% maximum boost pressure instantly off idle." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Chain-driven internal gear pump.", thermostatOpening: "87°C (Buried under supercharger).", oilCooler: "Water-to-Oil heat exchanger." }, fuelSystem: { systemType: "Direct Injection (FSI).", maxPressure: "150 Bar.", injectors: "Bosch high-pressure solenoids." }, tuningLimits: { maxSafeTorqueStock: "Approx. 600 Nm.", maxSafePowerStock: "Approx. 550 hp.", maxSafeRPM: "7200 RPM", weakestLink: "Catalytic converters melting, heat soak, and the DSG clutch packs." }, electrical: { coils: "COP.", ecu: "Simos 8.5" } },
