            engineeringData: { blockDesign: "Cast Iron closed deck (EA888 Gen 2). Extremely strong, but plagued by component flaws.", crankshaft: "Forged Steel, highly durable.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "140 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum. The oil control rings are fundamentally flawed (too thin with insufficient drainage).", wristPinDiameter: "21 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "58.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.70" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-flow 4-valve per cylinder.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Dual Overhead Camshafts driven by chain.", lifterType: "Hydraulic Roller Finger Follower.", specialFeature: "Direct injection only." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Chain-driven variable displacement.", thermostatOpening: "95°C.", oilCooler: "Water-to-Oil heat exchanger." }, fuelSystem: { systemType: "Direct Injection (FSI).", maxPressure: "150 Bar.", injectors: "Bosch multi-hole solenoids." }, tuningLimits: { maxSafeTorqueStock: "Approx. 400 Nm (Clutch limited).", maxSafePowerStock: "Approx. 320 hp.", maxSafeRPM: "6800 RPM", weakestLink: "Timing tensioner, PCV, factory clutch, and piston rings." }, electrical: { coils: "COP.", ecu: "Bosch MED 17.5" } },
