            tuningPotential: [ { stage: "Stage 1", power: "185 - 195 hp", notes: "An EDC17 ECU flash safely unlocks massive torque. The factory manual clutch WILL slip instantly under the torque spike (400+ Nm). Do NOT tune the Multitronic CVT.", zeroToHundred: "8.0s", hundredToTwoHundred: "N/A" }, { stage: "Stage 2", power: "205 - 215 hp", notes: "Requires a full DPF and EGR DELETE. Transforms the car entirely, making it incredibly punchy while removing the emissions failure risks.", zeroToHundred: "7.4s", hundredToTwoHundred: "N/A" }, { stage: "Stage 3 (Hybrid Turbo)", power: "240 - 250+ hp", notes: "Requires swapping the turbo for a larger hybrid unit and a 4-bar MAP sensor. The EA189 bottom end handles this beautifully.", zeroToHundred: "6.7s", hundredToTwoHundred: "N/A" } ],
