            engineeringData: { blockDesign: "Cast Iron closed deck (EA189 Update). Incredibly heavy but practically indestructible.", crankshaft: "Forged Steel, driving an upgraded 100mm balance shaft module in the oil pan.", pistonSpeed: "14.5 m/s @ 4500 RPM.", alternator: "140 Amp.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with deep combustion bowls.", wristPinDiameter: "26 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "54.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.79" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-swirl 16-valve DOHC architecture.", valveSizes: "Intake: 26.6 mm / Exhaust: 24.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Dual Overhead Camshafts driven by a toothed belt.", lifterType: "Hydraulic Roller Finger Follower.", specialFeature: "Swirl flaps integrated into the intake manifold. Uses reliable solenoid injectors." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Gear-driven balancer shaft module utilizing a 100mm hex key.", thermostatOpening: "87°C.", oilCooler: "Water-to-Oil heat exchanger." }, fuelSystem: { systemType: "Common Rail Direct Injection.", maxPressure: "1,800 Bar.", injectors: "Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "Approx. 400 Nm (Clutch limited).", maxSafePowerStock: "Approx. 230 hp.", maxSafeRPM: "5000 RPM", weakestLink: "The CP4 fuel pump and factory clutch." }, electrical: { coils: "N/A (Compression ignition).", ecu: "Bosch EDC 17" } },
            recommendedParts: { description: "The CJCD is one of the most robust versions of the EA189. Change the fuel filter religiously to protect the CP4 pump, and monitor the DPF.", parts: [ { category: "Timing Belt & Water Pump Kit", brand: "Continental", note: "CT1139WP6 kit. Mandatory at 210k km." }, { category: "CP4 Bypass Kit", brand: "Whitbread", note: "Saves the injectors if the pump fails." }, { category: "Fuel Filter", brand: "Mahle", note: "Replace every 30k km to save the CP4." }, { category: "EGR Valve", brand: "Pierburg", note: "Clogs with carbon constantly." }, { category: "Dual Mass Flywheel (DMF)", brand: "LuK", note: "Replaces vibrating factory unit." }, { category: "Glow Plugs", brand: "Beru", note: "Essential for cold starts and DPF regens." }, { category: "DPF Pressure Sensor", brand: "Bosch", note: "Fails frequently, stopping DPF regen." }, { category: "Oil Filter", brand: "Mann-Filter", note: "Cartridge filter." }, { category: "Thermostat", brand: "Mahle", note: "Replace if engine runs cold." }, { category: "Intake Flap Bracket", brand: "Dieselgeek", note: "Fixes P2015 code." } ] },
