            engineeringData: { blockDesign: "Cast Iron closed deck (EA888 Gen 3B). Highly advanced, lightweight casting.", crankshaft: "Forged Steel with 4 counterweights.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "Mild Hybrid 12V Belt Alternator Starter (BAS).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, specific B-Cycle high-compression crowns.", wristPinDiameter: "21 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "58.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.70" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-flow 4-valve per cylinder.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Dual Overhead Camshafts. Utilizes the 'B-Cycle' modified Miller cycle.", lifterType: "Hydraulic Roller Finger Follower.", specialFeature: "Audi Valvelift System (AVS) on the intake camshaft. Features Dual Injection and MHEV integration." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Chain-driven variable displacement.", thermostatOpening: "Electronic map-controlled module.", oilCooler: "Water-to-Oil heat exchanger." }, fuelSystem: { systemType: "Dual Injection (MPI + TFSI).", maxPressure: "250 Bar.", injectors: "4x Direct + 4x Port injectors." }, tuningLimits: { maxSafeTorqueStock: "Approx. 450 Nm.", maxSafePowerStock: "Approx. 320 hp.", maxSafeRPM: "6500 RPM", weakestLink: "The higher compression B-Cycle pistons, plastic water pump, and manual clutch." }, electrical: { coils: "COP.", ecu: "Bosch Simos 18.1" } },
