            tuningPotential: [ { stage: "Stage 1", power: "230 - 240 hp", notes: "An ECU flash completely transforms this engine. Because it is mechanically identical to the 190hp '40 TFSI' variant, it gains a colossal +85hp by simply removing the artificial software limits. The manual clutch WILL slip instantly under the torque spike.", zeroToHundred: "6.8s", hundredToTwoHundred: "17.0s" }, { stage: "Stage 2", power: "250 - 260 hp", notes: "Requires a high-flow downpipe and a front-mount intercooler.", zeroToHundred: "6.3s", hundredToTwoHundred: "15.5s" }, { stage: "Stage 3 (IS38 Swap)", power: "320 - 340+ hp", notes: "Requires swapping the factory turbo for an IHI IS38 (from the Golf R). Max power is limited by the high 11.6:1 compression ratio.", zeroToHundred: "5.5s", hundredToTwoHundred: "13.5s" } ],
            tuningGraphData: { stock: { hp: 150, nm: 270 }, stage1: { hp: 235, nm: 380 }, stage2: { hp: 255, nm: 410 }, stage3: { hp: 330, nm: 450 } },
