                torqueSpecs: [ { part: "Oil Drain Plug", value: "N/A", note: "Plastic plug requires 1/4 turn to lock. Must be replaced every oil change." }, { part: "Spark Plugs", value: "30 Nm", note: "Torque carefully to avoid stripping the aluminum cylinder head." }, { part: "Wheel Bolts", value: "120 Nm", note: "Tighten strictly in a star pattern." }, { part: "Water Pump Module Bolts", value: "9 Nm", note: "Plastic housing. Tighten strictly in a crisscross pattern." }, { part: "Ignition Coil Bolts", value: "10 Nm", note: "Do not overtighten the grounding bolts." }, { part: "Valve Cover Bolts", value: "9 Nm", note: "Tighten from center outwards." }, { part: "Oil Filter Housing Cap", value: "25 Nm", note: "Plastic cap." }, { part: "High-Pressure Fuel Pump Bolts", value: "20 Nm", note: "Tighten evenly." }, { part: "Turbocharger to Manifold Nuts", value: "25 Nm", note: "Use high-temp anti-seize." }, { part: "Camshaft Adjuster Magnet", value: "9 Nm", note: "Delicate aluminum threads." } ],
                engineeringData: { blockDesign: "Cast Iron closed deck (EA888 Gen 4 / Gen 3B Evo). An absolute masterpiece of modern engineering.", crankshaft: "Forged Steel, incorporating a chain-driven twin balance shaft system.", pistonSpeed: "15.0 m/s @ 6000 RPM.", alternator: "Mild Hybrid 12V Belt Alternator Starter (BAS).", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy, specific B-Cycle high-compression crowns.", wristPinDiameter: "21 mm", connectingRodLength: "144 mm", rodBoltSize: "M8.5 x 1.0", crankMainJournal: "58.0 mm", crankRodJournal: "47.8 mm", rodRatio: "1.70" }, cylinderHead: { combustionChamberVol: "N/A", intakePortFlow: "High-flow 4-valve per cylinder. The exhaust manifold is uniquely integrated directly into the cylinder head casting and is water-cooled.", valveSizes: "Intake: 33.8 mm / Exhaust: 28.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Dual Overhead Camshafts. Utilizes the 'B-Cycle' modified Miller cycle.", lifterType: "Hydraulic Roller Finger Follower.", specialFeature: "Audi Valvelift System (AVS) on the intake camshaft. Integrated 12V MHEV system for advanced engine-off coasting." }, oilAndCooling: { oilSquirters: "Yes", oilPumpType: "Chain-driven variable displacement vane pump.", thermostatOpening: "Electronic map-controlled module.", oilCooler: "Water-to-Oil heat exchanger." }, fuelSystem: { systemType: "Direct Injection (FSI).", maxPressure: "250 Bar.", injectors: "Bosch high-pressure solenoids." }, tuningLimits: { maxSafeTorqueStock: "Approx. 480 Nm.", maxSafePowerStock: "Approx. 320 hp.", maxSafeRPM: "6500 RPM", weakestLink: "The higher compression B-Cycle pistons, plastic water pump, and MHEV electronic limiters." }, electrical: { coils: "COP.", ecu: "Bosch Simos 19.x" } },
                recommendedParts: { description: "The DMSA 40 TFSI is a phenomenal engine. Focus solely on preventative maintenance of the cooling system and the strict 0W-20 oil requirement.", parts: [ { category: "Aluminum Water Pump", brand: "Graf / INA", note: "CRITICAL: Replaces the fragile factory plastic housing with a durable aluminum version." }, { category: "PCV Valve", brand: "Vaico", note: "The internal diaphragm tears frequently. Cures whistling noises and rough idle." }, { category: "Spark Plugs", brand: "NGK", note: "PLFER7A8EG platinum plugs." }, { category: "Ignition Coils (R8 Upgrade)", brand: "NGK", note: "Red R8 coils for a stronger spark." }, { category: "Oil Filter", brand: "Mann-Filter", note: "Top-mounted cartridge filter." }, { category: "High Pressure Fuel Pump", brand: "Hitachi", note: "Highly reliable." }, { category: "Camshaft Adjuster Magnet", brand: "Pierburg", note: "Fixes erratic idle and VVT codes." }, { category: "Plastic Drain Plug", brand: "Elring", note: "MUST be replaced at every single oil change." }, { category: "Diverter Valve (Rev D)", brand: "Pierburg", note: "Piston-style OEM upgrade." }, { category: "DSG Transmission Filter", brand: "Vaico", note: "Vital component for S-Tronic fluid service." } ] },
