                tuningPotential: [ { stage: "Stage 1", power: "250 - 265 hp", notes: "A Simos ECU flash safely unlocks significant power. The factory IS20 turbo provides a punchy +60hp jump. Absolute peak power is limited by the B-Cycle 11.6:1 compression ratio.", zeroToHundred: "6.2s", hundredToTwoHundred: "16.0s" }, { stage: "Stage 2", power: "275 - 290 hp", notes: "Requires a high-flow downpipe, full decat exhaust (difficult with GPF), and a front-mount intercooler. Transforms the car entirely.", zeroToHundred: "5.8s", hundredToTwoHundred: "14.5s" }, { stage: "Stage 3 (IS38 Swap)", power: "320 - 340+ hp", notes: "Requires swapping the factory turbo for an IHI IS38 (from the Golf R) and adding a massive FMIC. Absolute max power is heavily limited by the B-Cycle compression to avoid knock.", zeroToHundred: "5.2s", hundredToTwoHundred: "12.8s" } ],
