        engineMechanical: [ { interval: "4 Years", timeLimit: "4 years", task: "48V System Check", details: "Diagnostic check of MHEV battery.", parts: ["None"], importance: "High", laborDifficulty: "Easy", estimatedCost: "50 - 100" } ] 
