    tuningPotential: [ { stage: "Stage 1", power: "400 - 410 hp", notes: "An MG1 ECU flash tunes the petrol engine to match standard Stage 1 EA888 outputs, resulting in an aggressive combined system output. System torque is strictly capped to protect the hybrid-integrated DSG transmission.", zeroToHundred: "4.9s", hundredToTwoHundred: "13.5s" }, { stage: "Stage 2", power: "420 - 440 hp", notes: "Requires a high-flow GPF-back exhaust and upgraded intercooler. Very difficult to map correctly due to hybrid torque blending.", zeroToHundred: "4.6s", hundredToTwoHundred: "12.0s" }, { stage: "Stage 3 (IS38 Hybrid Turbo)", power: "470 - 500 hp", notes: "Requires swapping the factory turbo for a larger unit (e.g., Golf R IS38). Extremely rare on PHEV models due to the sheer complexity of calibrating the electric motor handoff with a massive turbo.", zeroToHundred: "4.1s", hundredToTwoHundred: "10.0s" } ],
